function validate([maximumHeight]) {
  if (!Array.isArray(maximumHeight) || maximumHeight.length < 1 || maximumHeight.length > 100000) return 'maximumHeight needs 1 to 10^5 values.';
  if (maximumHeight.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each maximum height is an integer from 1 to 10^9.';
  return null;
}

