function maximumTotalSum(maximumHeight) {
  const sorted = [...maximumHeight].sort((a, b) => b - a);
  let total = 0;
  let previous = Infinity;

  for (const limit of sorted) {
    const height = Math.min(limit, previous - 1);
    if (height <= 0) {
      return -1;
    }
    total += height;
    previous = height;
  }
  return total;
}

