function maximumTotalSum(maximumHeight) {
  // Exhaustive search. Tower i only tries heights limit, limit - 1, ..., limit - (n - 1): if it stood lower,
  // one of those n heights would be free (the other towers use at most n - 1) and taller, so it is never optimal.
  const n = maximumHeight.length;
  const rest = new Array(n + 1).fill(0);
  for (let i = n - 1; i >= 0; i--) rest[i] = rest[i + 1] + maximumHeight[i];
  const used = new Set();
  let best = -1;
  const search = (i, total) => {
    if (i === n) { best = Math.max(best, total); return; }
    if (total + rest[i] <= best) return;
    for (let h = maximumHeight[i]; h >= 1 && h > maximumHeight[i] - n; h--) {
      if (used.has(h)) continue;
      used.add(h);
      search(i + 1, total + h);
      used.delete(h);
    }
  };
  search(0, 0);
  return best;
}

