function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 6);
    if (rand() < 0.2) return [Array.from({ length: n }, () => 1000000000 - int(0, 6))];
    const top = int(1, 8);
    return [Array.from({ length: n }, () => int(1, top))];
  }
  const n = int(1500, 2000);
  const shape = Math.floor(rand() * 4);
  if (shape === 0) return [Array.from({ length: n }, () => int(1, 1000000000))];
  // Many repeats but enough room below them: always possible.
  if (shape === 1) return [Array.from({ length: n }, () => int(n, n + 300))];
  // Every limit is below n, so n distinct positive heights cannot fit: the answer is -1.
  if (shape === 2) return [Array.from({ length: n }, () => int(1, n - 1))];
  return [Array.from({ length: n }, () => 1000000000 - int(0, 50))];
}
